 const analysisIncomplete=cameraFailed.current.length>0||failed.current.length>0;const result=await api('attempt/'+active.current.id+'/submit',{analysisIncomplete});setDone({...result,analysisIncomplete});active.current=null;stream.current?.getTracks().forEach(t=>t.stop());cameraStream.current?.getTracks().forEach(t=>t.stop());setRecording(false);
